9	/**
10	 * Emits an audit line for a freshly created owner via the dedicated {@code AUDIT}
11	 * logger. Runs after {@link SaveOwner}, so the owner id has been assigned and the
12	 * line carries the id, the customerCode, the registrationDate, the membershipLevel
13	 * and the membershipNumber.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner) {
20	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
21	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
22	                owner.getMembershipLevel(), owner.getMembershipNumber());
23	    }
24	}
