293	    /**
294	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
295	     */
296	    @Transient
297	    public String getDisplayName() {
298	        return this.getLastName() + ", " + this.getFirstName();
299	    }
300	
301	    /**
302	     * The owner's initials: the upper-cased first letters of firstName and
303	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
304	     */
305	    @Transient
306	    public String getInitials() {
307	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
308	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
309	    }
310	
311	    /**
312	     * The fiscal year (starting 1 July) that the registration date falls in, as a
313	     * number: a date on or after 1 July belongs to the fiscal year of its own calendar
314	     * year, an earlier date belongs to the previous calendar year's fiscal year. Single
315	     * source of truth for the fiscal year, so {@link #getFiscalYear()}, the
316	     * {@link #getMembershipNumber() membership number} year segment and the tenure count
317	     * in {@link #getMembershipPoints()} cannot drift apart.
318	     */
319	    private static int fiscalYearOf(LocalDate date) {
320	        int year = date.getYear();
321	        return date.getMonthValue() >= Month.JULY.getValue() ? year : year - 1;
322	    }
323	
324	    /**
325	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the last two
326	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted
327	     * {@link #registrationDate} (e.g. {@code "FY26"} for a date in July 2026 to
328	     * June 2027). Derived from the owner's own fields; null when the registration date
329	     * is absent.
330	     */
331	    @Transient
332	    public String getFiscalYear() {
333	        if (this.registrationDate == null) {
334	            return null;
335	        }
336	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
337	    }
338	
339	    /**
340	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
341	     * YY is the last two digits of the registration date's fiscal year (starting
342	     * 1 July; e.g. {@code "NSW-A1B2C3D4-M26"} for a date in July 2026 to June 2027).
343	     * Derived from the owner's own fields; null when either the customer code or
344	     * registration date is absent.
345	     */
346	    @Transient
347	    public String getMembershipNumber() {
348	        if (this.customerCode == null || this.registrationDate == null) {
349	            return null;
350	        }
351	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
352	    }
353	
354	    /**
355	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
356	     * contained in the {@code customerCode}, scanning right to left and doubling the
357	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
358	     * own fields; null when the customer code is absent.
359	     */
360	    @Transient
361	    public Integer getCheckDigit() {
362	        if (this.customerCode == null) {
363	            return null;
364	        }
365	        int sum = 0;
366	        boolean dbl = true;
367	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
368	            char c = this.customerCode.charAt(i);
369	            if (c < '0' || c > '9') {
370	                continue;
371	            }
372	            int d = c - '0';
373	            if (dbl) {
374	                d *= 2;
375	                if (d > 9) {
376	                    d -= 9;
377	                }
378	            }
379	            sum += d;
380	            dbl = !dbl;
381	        }
382	        return (10 - (sum % 10)) % 10;
383	    }
384	
385	    /**
386	     * The owner's membership points: a running score built from the owner's own fields.
387	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
388	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
389	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
390	     * for tenure of more than one elapsed fiscal year (the fiscal years, starting 1 July,
391	     * from {@link #registrationDate} to the current date). A newly created owner has zero
392	     * tenure, so the pre-tenure factors alone top out at 5 points. Derived from the owner's
393	     * own fields.
394	     */
395	    @Transient
396	    public Integer getMembershipPoints() {
397	        int points = 0;
398	        boolean hasEmail = this.email != null && !this.email.isBlank();
399	        if (hasEmail) {
400	            points += 2;
401	        }
402	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
403	        if (unique) {
404	            points += 1;
405	        }
406	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
407	        if (largeHousehold) {
408	            points += 2;
409	        }
410	        boolean tenured = this.registrationDate != null
411	            && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate)) > 1;
412	        if (tenured) {
413	            points += 3;
414	        }
415	        return points;
416	    }
417	
418	    /**
419	     * The owner's membership level: a number from 1 to 4 derived by banding
420	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
421	     * or more. Derived from the owner's own fields, then capped by
422	     * {@link #membershipLevelCap} when set: a new owner's level cannot exceed one above the
423	     * current maximum level among their household members. With no existing household member
424	     * the cap is absent and the banded value stands.
425	     */
426	    @Transient
427	    public Integer getMembershipLevel() {
428	        int level = bandMembershipLevel(getMembershipPoints());
429	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
430	            return this.membershipLevelCap;
431	        }
432	        return level;
433	    }
434	
435	    private static int bandMembershipLevel(int points) {
436	        if (points <= 1) {
437	            return 1;
438	        }
439	        if (points <= 3) {
440	            return 2;
441	        }
442	        if (points <= 5) {
443	            return 3;
444	        }
445	        return 4;
446	    }
447	
448	    /**
449	     * Fixed city-to-region lookup table. Any city not listed derives locality
450	     * {@code "UNKNOWN"}.
451	     */
452	    private static final Map<String, String> CITY_REGION = Map.of(
453	        "Sydney", "NSW",
454	        "Melbourne", "VIC",
455	        "Brisbane", "QLD");
456	
457	    /**
458	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
459	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
460	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
461	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
462	     * postcode validation).
463	     */
464	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
465	        "NSW", new int[] {2000, 2099},
466	        "VIC", new int[] {3000, 3099},
467	        "QLD", new int[] {4000, 4099});
468	
469	    /**
470	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
471	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
472	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
473	     */
474	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
475	        "NSW", "Australia/Sydney",
476	        "VIC", "Australia/Melbourne",
477	        "QLD", "Australia/Brisbane");
478	
479	    /**
480	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
481	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
482	     * a customer code is present, otherwise derived straight from the postcode via
483	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
484	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
485	     * no known range. Derived from the owner's own fields.
486	     */
487	    @Transient
488	    public String getLocality() {
489	        if (this.customerCode != null) {
490	            int dash = this.customerCode.indexOf('-');
491	            if (dash > 0) {
492	                return this.customerCode.substring(0, dash);
493	            }
494	        }
495	        return identityRegion(this.postcode);
496	    }
497	
498	    /**
499	     * The REGION component of an owner's region-and-hash identity: the region derived from
500	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
501	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
502	     * of truth for the identity's region, so the {@code customerCode} prefix and the
503	     * {@link #getLocality() locality} cannot drift apart.
504	     */
505	    public static String identityRegion(String postcode) {
506	        String region = regionForPostcode(postcode);
507	        return region != null ? region : "UNKNOWN";
508	    }
509	
510	    /**
511	     * The canonical region for a city per the fixed city-to-region table
512	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
513	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
514	     * for the city-to-region mapping, used as the city's region in postcode validation.
515	     */
516	    public static String regionForCity(String city) {
517	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
518	    }
519	
520	    /**
521	     * The canonical region for a 4-digit postcode per the fixed range table
522	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
523	     * is absent, not a well-formed integer, or in no known range. Reads the shared
524	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
525	     * for the identity's region and by postcode validation to range-check a submitted
526	     * postcode against its city's region.
527	     */
528	    public static String regionForPostcode(String postcode) {
529	        if (postcode == null) {
530	            return null;
531	        }
532	        int value;
533	        try {
534	            value = Integer.parseInt(postcode.trim());
535	        } catch (NumberFormatException ex) {
536	            return null;
537	        }
538	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
539	            int[] range = entry.getValue();
540	            if (value >= range[0] && value <= range[1]) {
541	                return entry.getKey();
542	            }
543	        }
544	        return null;
545	    }
546	
547	    /**
548	     * Whether the region is subject to postcode range validation, i.e. has a known
549	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
550	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
551	     */
552	    public static boolean hasPostcodeRange(String region) {
553	        return REGION_POSTCODE_RANGES.containsKey(region);
554	    }
555	
556	    /**
557	     * The owner's IANA timezone, derived from the owner's {@link #getLocality() locality}
558	     * (its region) via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
559	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Null when the
560	     * region is not one of these (e.g. {@code "UNKNOWN"}). Derived from the owner's own
561	     * fields.
562	     */
563	    @Transient
564	    public String getTimezone() {
565	        return REGION_TIMEZONE.get(getLocality());
566	    }
567	
568	    /**
569	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
570	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
571	     */
572	    @Transient
573	    public String getContactPreference() {
574	        boolean hasEmail = this.email != null && !this.email.isBlank();
575	        return hasEmail ? "EMAIL" : "PHONE";
576	    }
577	
578	    /**
579	     * The owner's identity key: the lower-case hex SHA-256 of
580	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}. The
581	     * telephone is already stored in E.164 form, the email is lower-cased (an empty segment
582	     * when absent), and the last name is reduced to its {@link #soundex(String) Soundex}
583	     * code. This is the single identity used for duplicate detection: two owners with the
584	     * same key are the same person (a 409 on create); an owner whose key differs but whose
585	     * Soundex last name and postcode match an existing owner is a soft match instead.
586	     * Derived from the owner's own fields.
587	     */
588	    @Transient
589	    public String getIdentityKey() {
590	        String normalizedTelephone = keyPart(this.telephone);
591	        String lowerEmail = keyPart(this.email == null ? null : this.email.toLowerCase(Locale.ROOT));
592	        String soundexLastName = soundex(this.getLastName());
593	        return sha256Hex(normalizedTelephone + "|" + lowerEmail + "|" + soundexLastName);
594	    }
595	
596	    private static String keyPart(String value) {
597	        return (value == null || value.isBlank()) ? "" : value;
598	    }
599	
600	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
601	    private static String sha256Hex(String value) {
602	        try {
603	            byte[] digest = MessageDigest.getInstance("SHA-256")
604	                .digest(value.getBytes(StandardCharsets.UTF_8));
605	            StringBuilder sb = new StringBuilder(digest.length * 2);
606	            for (byte b : digest) {
607	                sb.append(String.format("%02x", b));
608	            }
609	            return sb.toString();
610	        }
611	        catch (NoSuchAlgorithmException ex) {
612	            throw new IllegalStateException("SHA-256 not available", ex);
613	        }
614	    }
615	
616	    /**
617	     * The American Soundex code of {@code name}: the upper-cased first letter followed by
618	     * three digits that encode the remaining consonants. Vowels and {@code H}/{@code W} are
619	     * not coded; adjacent letters with the same code collapse to one, as do two same-coded
620	     * letters separated only by {@code H} or {@code W}. The code is right-padded with zeros
621	     * and truncated to four characters. An absent or letter-free name yields the empty
622	     * string. The single source of truth for an owner's last-name phonetic key, used by the
623	     * {@link #getIdentityKey() identity key} and by soft-duplicate matching. It lives here
624	     * (rather than beside the exact-match name normalization in the package-private
625	     * {@code OwnerNames} helper) because {@code getIdentityKey()} is an entity-level derived
626	     * getter and must not depend on the request-function layer; the two are distinct name
627	     * concerns — exact comparison vs. phonetic keying — not a duplicated utility.
628	     */
629	    public static String soundex(String name) {
630	        if (name == null) {
631	            return "";
632	        }
633	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
634	        if (letters.isEmpty()) {
635	            return "";
636	        }
637	        StringBuilder code = new StringBuilder();
638	        code.append(letters.charAt(0));
639	        char prev = soundexDigit(letters.charAt(0));
640	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
641	            char c = letters.charAt(i);
642	            char digit = soundexDigit(c);
643	            if (digit != '0' && digit != prev) {
644	                code.append(digit);
645	            }
646	            // Vowels reset the previous code so same-coded consonants either side are coded
647	            // twice; H and W do not, so same-coded letters they separate still collapse.
648	            if (c != 'H' && c != 'W') {
649	                prev = digit;
650	            }
651	        }
652	        while (code.length() < 4) {
653	            code.append('0');
654	        }
655	        return code.toString();
656	    }
657	
658	    private static char soundexDigit(char c) {
659	        switch (c) {
660	            case 'B': case 'F': case 'P': case 'V':
661	                return '1';
662	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
663	                return '2';
664	            case 'D': case 'T':
665	                return '3';
666	            case 'L':
667	                return '4';
668	            case 'M': case 'N':
669	                return '5';
670	            case 'R':
671	                return '6';
672	            default:
673	                return '0';
674	        }
675	    }
676	
677	    /**
678	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
679	     * a space, then the national digits grouped in threes (e.g.
680	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
681	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
682	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
683	     * and the national digits follow in space-separated groups of three. Returns the raw
684	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
685	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
686	     */
687	    @Transient
688	    public String getTelephoneDisplay() {
689	        if (this.telephone == null || !this.telephone.startsWith("+")) {
690	            return this.telephone;
691	        }
692	        String digits = this.telephone.substring(1);
693	        if (!digits.matches("\\d+")) {
694	            return this.telephone;
695	        }
696	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
697	        if (digits.length() <= countryCodeLength) {
698	            return this.telephone;
699	        }
700	        String countryCode = digits.substring(0, countryCodeLength);
701	        String national = digits.substring(countryCodeLength);
702	        StringBuilder grouped = new StringBuilder();
703	        for (int i = 0; i < national.length(); i += 3) {
704	            if (grouped.length() > 0) {
705	                grouped.append(' ');
706	            }
707	            grouped.append(national, i, Math.min(i + 3, national.length()));
708	        }
709	        return "+" + countryCode + " " + grouped;
710	    }
711	
712	    protected Set<Pet> getPetsInternal() {
713	        if (this.pets == null) {
714	            this.pets = new HashSet<>();
715	        }
716	        return this.pets;
717	    }
718	
719	    protected void setPetsInternal(Set<Pet> pets) {
720	        this.pets = pets;
721	    }
722	
723	    public List<Pet> getPets() {
724	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
725	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
726	        return Collections.unmodifiableList(sortedPets);
727	    }
728	
729	    public void setPets(List<Pet> pets) {
730	        this.pets = new HashSet<>(pets);
731	    }
732	
733	    public void addPet(Pet pet) {
734	        getPetsInternal().add(pet);
735	        pet.setOwner(this);
736	    }
737	
738	    /**
739	     * Return the Pet with the given name, or null if none found for this Owner.
740	     *
741	     * @param name to test
742	     * @return true if pet name is already in use
743	     */
744	    public Pet getPet(String name) {
745	        return getPet(name, false);
746	    }
747	
748	    /**
749	     * Return the Pet with the given name, or null if none found for this Owner.
750	     *
751	     * @param name to test
752	     * @return true if pet name is already in use
753	     */
754	    public Pet getPet(String name, boolean ignoreNew) {
755	        name = name.toLowerCase();
756	        for (Pet pet : getPetsInternal()) {
757	            if (!ignoreNew || !pet.isNew()) {
758	                String compName = pet.getName();
759	                compName = compName.toLowerCase();
760	                if (compName.equals(name)) {
761	                    return pet;
762	                }
763	            }
764	        }
765	        return null;
766	    }
767	
768	    public Pet getPet(Integer petId) {
769	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
770	    }
771	
772	    @Override
773	    public String toString() {
774	        return new ToStringCreator(this)
775	
776	            .append("id", this.getId())
777	            .append("new", this.isNew())
778	            .append("lastName", this.getLastName())
779	            .append("firstName", this.getFirstName())
780	            .append("address", this.address)
781	            .append("city", this.city)
782	            .append("telephone", this.telephone)
783	            .append("email", this.email)
784	            .toString();
785	    }
786	}
