1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Caps the new owner's {@code membershipLevel} at one above the current maximum
9	 * {@code membershipLevel} among their household members — the existing owners that share
10	 * the owner's household ({@code (lastName, postcode)}, keyed by {@link Households}).
11	 * Runs after {@link AssignHousehold} has stamped the {@code householdId}, so it reflects
12	 * that same household definition, and before the owner is saved, so the owner being
13	 * created is not counted among the existing members.
14	 *
15	 * <p>The cap is the highest member level plus one, stored on the owner so that
16	 * {@link Owner#getMembershipLevel()} clamps the banded value to it. With no existing
17	 * household member (including an owner with no postcode, which belongs to no household)
18	 * no cap is set and the banded level stands. Which owners count as household members is
19	 * defined once by {@link Households#members}.
20	 */
21	public class CapMembershipLevel {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        Integer maxLevel = null;
25	        for (Owner member : Households.members(owner.getHouseholdId(), ownerRepository.findAll())) {
26	            Integer level = member.getMembershipLevel();
27	            if (level != null && (maxLevel == null || level > maxLevel)) {
28	                maxLevel = level;
29	            }
30	        }
31	        if (maxLevel != null) {
32	            owner.setMembershipLevelCap(maxLevel + 1);
33	        }
34	    }
35	}
